package main

// Purpose: writeCounts and writeRegistry's success, idempotence, render-
//
//	failure, and write-failure paths. run and repoRoot's own tests live in
//	run_test.go (split purely to stay under the 300-line-per-file cap).
//
// Constraints: this generator's whole reason to exist is that a tracked
//
//	artifact never silently drifts from what it claims to represent
//	(main.go's own doc comment); a generator with no test coverage is
//	exactly how that guarantee quietly stops holding, so every test here
//	proves a real property of the generated bytes, never merely that a
//	call returned without panicking.
//
// SPORT: internal.inventory.gen/ADDED (tests),
//
//	internal.inventory.gen.registry/ADDED (tests).

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/acamarata/cascade/internal/output"
	"github.com/acamarata/cascade/internal/runtime"
)

func testWriter() *output.Writer {
	return output.New(&bytes.Buffer{}, &bytes.Buffer{}, false, false, false, false)
}

func fixedClock() runtime.Clock {
	return runtime.NewFixedClock(time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
}

func TestWriteCounts_Success(t *testing.T) {
	root := buildGenFixtureRepo(t)
	if err := writeCounts(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeCounts: %v", err)
	}
	outPath := filepath.Join(root, "internal", "inventory", "counts.json")
	data, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading written counts.json: %v", err)
	}
	if !bytes.Contains(data, []byte(`"providers": 1`)) {
		t.Fatalf("counts.json = %s, want providers: 1 (one fixture provider dir)", data)
	}
	if !bytes.Contains(data, []byte(`"plugins": 1`)) {
		t.Fatalf("counts.json = %s, want plugins: 1 (one fixture plugin dir)", data)
	}
}

// TestWriteCounts_Idempotent proves two writeCounts calls against the same
// unchanged tree with the same fixed clock produce byte-identical bytes
// on disk — the generator's core idempotence property (12-QUALITY-
// CONSTITUTION.md Art.7), checked here at the file-writing layer rather
// than only at RenderCounts' own already-tested pure-function layer.
func TestWriteCounts_Idempotent(t *testing.T) {
	root := buildGenFixtureRepo(t)
	outPath := filepath.Join(root, "internal", "inventory", "counts.json")

	if err := writeCounts(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeCounts (first): %v", err)
	}
	first, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading counts.json after first write: %v", err)
	}
	if err := writeCounts(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeCounts (second): %v", err)
	}
	second, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading counts.json after second write: %v", err)
	}
	if !bytes.Equal(first, second) {
		t.Fatalf("writeCounts is not idempotent:\nfirst:  %s\nsecond: %s", first, second)
	}
}

// TestWriteCounts_RenderError proves a tree RenderCounts cannot compute
// over (no providers/) refuses before ever touching the output file.
func TestWriteCounts_RenderError(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "internal", "inventory"), 0o755); err != nil {
		t.Fatalf("mkdir output dir: %v", err)
	}
	if err := writeCounts(testWriter(), root, fixedClock()); err == nil {
		t.Fatal("writeCounts over a tree with no providers/: want an error, got nil")
	}
	outPath := filepath.Join(root, "internal", "inventory", "counts.json")
	if _, err := os.Stat(outPath); !os.IsNotExist(err) {
		t.Fatalf("writeCounts left a partial artifact at %s after a render failure", outPath)
	}
}

// TestWriteCounts_UnwritableDestination proves a destination directory
// that does not exist is refused with a wrapped error naming the path,
// not a panic or a silently swallowed failure.
func TestWriteCounts_UnwritableDestination(t *testing.T) {
	root := buildGenFixtureRepo(t)
	if err := os.RemoveAll(filepath.Join(root, "internal")); err != nil {
		t.Fatalf("removing internal/: %v", err)
	}
	err := writeCounts(testWriter(), root, fixedClock())
	if err == nil {
		t.Fatal("writeCounts with a missing destination directory: want an error, got nil")
	}
}

func TestWriteRegistry_Success(t *testing.T) {
	root := buildGenFixtureRepo(t)
	if err := writeRegistry(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeRegistry: %v", err)
	}
	outPath := filepath.Join(root, "internal", "inventory", "sport", "registry.json")
	data, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading written registry.json: %v", err)
	}
	if !bytes.Contains(data, []byte(`"fixture.alpha"`)) || !bytes.Contains(data, []byte(`"fixture.gamma"`)) {
		t.Fatalf("registry.json = %s, want both fixture entities present", data)
	}
}

// TestWriteRegistry_Idempotent mirrors TestWriteCounts_Idempotent for the
// registry artifact: entities and sites must be sorted, not emitted in
// (nondeterministic) map iteration order, or two runs over the same tree
// would diff on every regeneration.
func TestWriteRegistry_Idempotent(t *testing.T) {
	root := buildGenFixtureRepo(t)
	outPath := filepath.Join(root, "internal", "inventory", "sport", "registry.json")

	if err := writeRegistry(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeRegistry (first): %v", err)
	}
	first, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading registry.json after first write: %v", err)
	}
	if err := writeRegistry(testWriter(), root, fixedClock()); err != nil {
		t.Fatalf("writeRegistry (second): %v", err)
	}
	second, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("reading registry.json after second write: %v", err)
	}
	if !bytes.Equal(first, second) {
		t.Fatalf("writeRegistry is not idempotent:\nfirst:  %s\nsecond: %s", first, second)
	}
}

// TestWriteRegistry_MalformedInputRefuses proves a SPORT marker with no
// extractable entity name fails the whole render closed, matching
// internal/inventory/sport's own ComputeRegistry contract, rather than
// silently dropping that one line from the tracked registry.
func TestWriteRegistry_MalformedInputRefuses(t *testing.T) {
	root := buildGenFixtureRepo(t)
	addMalformedSPORTFile(t, root)

	err := writeRegistry(testWriter(), root, fixedClock())
	if err == nil {
		t.Fatal("writeRegistry over a malformed SPORT marker: want an error, got nil")
	}
	outPath := filepath.Join(root, "internal", "inventory", "sport", "registry.json")
	if _, statErr := os.Stat(outPath); !os.IsNotExist(statErr) {
		t.Fatalf("writeRegistry left a partial artifact at %s after a malformed-input failure", outPath)
	}
}

// TestWriteRegistry_UnwritableDestination mirrors
// TestWriteCounts_UnwritableDestination for the registry artifact.
func TestWriteRegistry_UnwritableDestination(t *testing.T) {
	root := buildGenFixtureRepo(t)
	if err := os.RemoveAll(filepath.Join(root, "internal", "inventory", "sport")); err != nil {
		t.Fatalf("removing internal/inventory/sport/: %v", err)
	}
	if err := writeRegistry(testWriter(), root, fixedClock()); err == nil {
		t.Fatal("writeRegistry with a missing destination directory: want an error, got nil")
	}
}
